1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Identity duplicate detection for create-owner — "the duplicate block", now the single duplicate
10	 * check (the old household-duplicate 409 no longer exists). Detection keys off the full
11	 * {@link IdentityKey} — the SHA-256 hex over {@code normalizedTelephone + '|' + lowerEmail + '|' +
12	 * soundex(lastName)}: a create is rejected via {@link DuplicateIdentityException} (turned into a 409 by
13	 * the global handler) only when its identityKey collides with an existing owner's. Because the
14	 * telephone is part of the key, distinct members of the same household — same last name and postcode
15	 * but different telephones — derive different identityKeys and coexist; only a genuine identity
16	 * collision is rejected. Such household members are instead flagged by the soft-match
17	 * ({@link DetectPossibleDuplicate}).
18	 *
19	 * <p>A request that sets {@code sharesHousehold} true bypasses this block: it is a declared household
20	 * member and is created. Runs before the owner is built and saved, so
21	 * {@link OwnerRepository#findAll()} sees only the owners that existed before this create.
22	 */
23	public class RejectDuplicateOwner {
24	
25	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
26	            throws DuplicateIdentityException {
27	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
28	            return; // declared household member — bypass the duplicate block
29	        }
30	        String identityKey = IdentityKey.of(request.getTelephone(), request.getEmail(),
31	                request.getLastName(), request.getPostcode());
32	        for (Owner existing : ownerRepository.findAll()) {
33	            if (Boolean.TRUE.equals(existing.getDeleted())) {
34	                continue; // soft-deleted owners are ignored by the duplicate check
35	            }
36	            String existingKey = IdentityKey.of(existing.getTelephone(), existing.getEmail(),
37	                    existing.getLastName(), existing.getPostcode());
38	            if (identityKey.equals(existingKey)) {
39	                throw new DuplicateIdentityException(identityKey);
40	            }
41	        }
42	    }
43	}
44

